import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long num = scanner.nextLong();
        long den = scanner.nextLong();
        long max_iter = scanner.nextLong();

        double ratio = (double) num / den;
        long best_num = 1;
        long best_den = 1;
        double min_diff = 1e9;
        double eps = 1e-25;

        if (den <= best_den) {
            System.out.println(num + "/" + den);
            return;
        }

        for (long i = 1; i <= max_iter; i++) {
            double val = ratio * i;
            long a1 = (long) Math.floor(val);
            long a2 = (long) Math.ceil(val);

            double diff = Math.abs(ratio - (double) a1 / i);
            if (diff < min_diff - eps) {
                min_diff = diff;
                best_num = a1;
                best_den = i;
            }

            diff = Math.abs((double) a2 / i - ratio);
            if (diff < min_diff - eps) {
                min_diff = diff;
                best_num = a2;
                best_den = i;
            }
        }

        System.out.println(best_num + "/" + best_den);
    }
}
